// Simulación mínima de Minecraft para probar el almacenamiento.
export const estado = { lista: true, entidades: [], props: new Map(), estructuras: new Map(), intervalos: [], tirados: [] };
let n = 0;
class Caja { constructor(t) { this.size = t; this.s = Array(t).fill(undefined); } getItem(i) { return this.s[i]; } setItem(i, v) { if (i >= this.size) throw new Error("fuera"); this.s[i] = v; } }
function entidad(tipo, loc) {
  const e = { id: String(n++), typeId: tipo, location: loc, tags: new Set(), caja: new Caja(256),
    addTag(t) { this.tags.add(t); }, getComponent() { return { container: this.caja }; },
    remove() { estado.entidades = estado.entidades.filter((x) => x !== this); } };
  estado.entidades.push(e); return e;
}
const dim = {
  getEntities: (q) => estado.entidades.filter((e) => (!q.type || e.typeId === q.type) && (!q.tags || q.tags.every((t) => e.tags.has(t)))),
  spawnEntity: (t, l) => entidad(t, l), getBlock: () => (estado.lista ? {} : undefined), runCommand() {},
  spawnItem: (it) => estado.tirados.push(it),
};
export const world = {
  getDimension: () => dim, afterEvents: { playerSpawn: { subscribe() {} } },
  getDynamicProperty: (k) => estado.props.get(k), setDynamicProperty: (k, v) => (v === undefined ? estado.props.delete(k) : estado.props.set(k, v)),
  getDynamicPropertyIds: () => [...estado.props.keys()],
  structureManager: {
    get: (k) => estado.estructuras.get(k),
    place: (k) => { const e = entidad("qidb:storage", {}); estado.estructuras.get(k).forEach((it, i) => e.caja.setItem(i, it)); },
    delete: (k) => estado.estructuras.delete(k),
  },
};
export const system = { runTimeout() {}, runInterval: (f) => estado.intervalos.push(f) };
